import { test } from "node:test";
import assert from "node:assert/strict";
import { swapWeeks, whoIsOnCall } from "./rota.js";

test("a swap gives each the other's week", () => {
  const rota = swapWeeks({ start: new Date("2026-01-05"), people: ["Ada", "Grace"] }, "Ada", "Grace");
  assert.equal(whoIsOnCall(rota, new Date("2026-01-07")), "Grace");
});
